export function appendXdgHistory(text: string): void {
  try {
    const dir = path.join(os.homedir(), ".local", "share", "muse");
    fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(
      path.join(dir, "tui-history.jsonl"),
      JSON.stringify(text) + "\n",
      "utf-8",
    );
  } catch {
    /* ignore */
  }
}
